"""
Second pass over the Qur'anic letter confusions: two reverts, and the words the
first pass left standing beside the ones it repaired.

WHY THERE IS A SECOND PASS. scripts/repair-quranic-letter-confusions.py worked
from the unmatched spans in translation-drafts/verse-match-report.json. That
list is a list of spans, not of citations, so the first pass repaired a word and
walked past its neighbour: `INQALABU` beside `INFALABU` in the next parenthesis
at Q 83:31, `al-MUTTAFIN` beside `al-MUTTAQUN` three words later at Q 39:33,
`fa-li-dhalika` repaired in one quotation of Q 42:15 and left in the re-quotation
ninety characters on. Half a repaired citation is worse than none: a reader who
sees both spellings cannot tell which half is the scan's and which is the
Shaykh's. 681 words, 717 letters, 51 lessons.

HOW THEY WERE FOUND. For every one of the 879 sites the first pass repaired, the
aya it quotes was re-derived by aligning the 700 characters round it against the
Warsh text in src/data/verse_text.json, and then every word in that
neighbourhood was tested against that same aya. A word is admissible evidence if
it stands inside a bracketed citation, or if it stands between two citation
words of the same aya in the aya's own word order -- the shape the compiler
makes when he walks an aya glossing as he goes and the scan has dropped one of
his brackets, as at Q 2:66, where `(bayna yadayha)` and `(wa-maw`izatan
li-l-muttaqin)` are bracketed and `wa-ma khalfaha` between them is not, with his
own gloss `al-umam allati ta'ti ba`daha` beside it.

Two tests ran over that neighbourhood and had to agree: a word-by-word alignment
against a nine-aya window, and a bag test that accepts a word only when the
folded form matches exactly ONE raw reading in the aya and its two neighbours.
Where two readings fit, neither runs.

WHAT WAS CUT BY HAND. 704 candidates came back and every one was read in
context. 28 were thrown out, and they are the reason this table is written out
site by site rather than left to the rule. They fall into three kinds:

  - the word is already right and the rule found it a rival elsewhere in the
    same aya: `ila rabbiki` (Q 89:28) offered as `an`, `wa-llahu ya`lamu
    a`malakum` (Q 47:30) as `na`lam`, `buyut akhwalikum` (Q 24:61) as
    `ikhwanikum`, `min al-DIN ma wassa bihi Nuhan` (Q 42:13) as `alladhin`,
    `ANA rabbukum al-a`la` (Q 79:24) and `INNA la-mab`uthun` (Q 17:49) as `alla`.
  - the parenthesis is not Qur'an. `qala` in the hadith `dhalika mal rabih`, and
    in the hadith of the five prayers, offered as `fa-inna`; `ya ABA Dharr`
    offered as `anna`; `thadyi yajri `alayka` -- a mother speaking -- offered as
    `yajzi`; and `ghalaba`, which is the compiler's own gloss on `rana` at
    Q 83:14, offered as `ala`.
  - the rule reached for the wrong word. Q 27:78 is `rabbaka YAQDI baynahum`,
    not `yaqussu`, so only the fa/qaf there is damage and the sad is not;
    Q 72:20 is `QUL innama ad`u rabbi`, which no letter swap reaches.

THE TWO REVERTS. Both were wrong in the worst way a pass like this can be wrong:
they replaced damage with plausible Arabic, which hides the defect instead of
marking it.

  - Lesson 16 @13075. The first pass wrote `TATIBA`A` over `TABI`A`, reading the
    site as Q 5:48 `wa-la tattabi` ahwa'ahum`. The site is Q 6:51 and the word is
    SHAFI`, which the compiler glosses two words later with `yashfa`u lahum` --
    a gloss of shafi` and of nothing in t-b-`. shin for ta plus fa for ba is
    outside the confusions this scan makes, so the word goes back as it was and
    onto the list for AK.
  - Lesson 8 @12249. The first pass wrote `MIN` over `MI`, reading the site as
    Q 10:45. The site is Q 3:27, `tuliju l-layla FI l-nahar`, and the compiler's
    gloss `tudkhilu l-layl` requires `fi`. The first pass's own docstring names
    this trap and lists five places where `mi` was left alone as `fi`; this one
    went through, and `min al-nahar` reads as Arabic, so nothing would have
    caught it later.

ANCHORING is as before: offsets into `arabicBody`, the exact codepoints expected
there, one letter for one letter so lengths and offsets hold, asserts if a file
has moved, and a site already carrying the repaired word is skipped.

  python3 scripts/complete-quranic-letter-confusions.py          # dry run
  python3 scripts/complete-quranic-letter-confusions.py --write


HOW A SITE IS IDENTIFIED (changed 21 September 2026)

This script no longer addresses its sites by a raw character offset.  Each row
carries the target word before and after the repair, plus the raw skeletons of
the words on either side as they stood when the row was minted; the old offset
survives only as `hint`, which orders the search and appears in reports.  The
resolver requires exactly one place in the field to carry that neighbourhood
and refuses to choose when more than one does.  Rows that share an anchor form
a group, and the group must name exactly as many places as it has rows -- that
is how a passage repeated verbatim inside one field is handled without ever
picking between its copies.

The change exists so that a repair may add or remove a character.  While every
row was an offset, nine scripts shared an unenforced contract that no pass ever
changed a length, and the whole class of dropped-letter damage was unreachable.
See scripts/repair_anchors.py.


HOW A SITE IS IDENTIFIED (changed 21 September 2026)

This script no longer addresses its sites by a raw character offset.  Each row
carries the target word before and after the repair, plus the raw skeletons of
the words on either side as they stood when the row was minted; the old offset
survives only as `hint`, which orders the search and appears in reports.  The
resolver requires exactly one place in the field to carry that neighbourhood
and refuses to choose when more than one does.  Rows that share an anchor form
a group, and the group must name exactly as many places as it has rows -- that
is how a passage repeated verbatim inside one field is handled without ever
picking between its copies.

The change exists so that a repair may add or remove a character.  While every
row was an offset, nine scripts shared an unenforced contract that no pass ever
changed a length, and the whole class of dropped-letter damage was unreachable.
See scripts/repair_anchors.py.
"""
